using System.Text.Json.Nodes; using Jsonata.Net.Core.Evaluation; namespace Jsonata.Net.Core.AstNodes; public sealed class NumericLiteralNode : AstNode {     public decimal Value { get; }     public NumericLiteralNode(decimal value) { this.Value = value; }     public override Sequence Evaluate(JsonNode? input, EvaluationContext context) {         return new Sequence(JsonValue.Create(this.Value));     } }
